import { useContext, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import './share.scss';

const Share = () => {
  const { currentUser, accessToken, refreshAccessToken } = useContext(AuthContext);
  const [desc, setDesc] = useState('');
  const [file, setFile] = useState(null);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!desc && !file) {
      setError('Please provide a description or file');
      return;
    }
    if (!currentUser) {
      setError('Please login to share a post');
      return;
    }

    const formData = new FormData();
    formData.append('userId', currentUser._id);
    formData.append('desc', desc);
    if (file) formData.append('media', file);

    try {
      console.log('Share: Creating post for user:', currentUser.name);
      const res = await axios.post('http://localhost:5000/api/posts', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: `Bearer ${accessToken}`,
        },
      });
      console.log('Share: Post created successfully, response:', res.data);
      setDesc('');
      setFile(null);
      setError(null);
      window.dispatchEvent(new Event('newPost'));
    } catch (err) {
      console.error('Share: Error creating post:', err.message, err.response?.data);
      if (err.response?.status === 401) {
        try {
          console.log('Share: Token expired, attempting to refresh');
          const newToken = await refreshAccessToken();
          const retryRes = await axios.post('http://localhost:5000/api/posts', formData, {
            headers: {
              'Content-Type': 'multipart/form-data',
              Authorization: `Bearer ${newToken}`,
            },
          });
          console.log('Share: Post created after refresh:', retryRes.data);
          setDesc('');
          setFile(null);
          setError(null);
          window.dispatchEvent(new Event('newPost'));
        } catch (refreshErr) {
          console.error('Share: Refresh failed:', refreshErr.message);
          setError('Session expired. Please login again.');
        }
      } else {
        setError(err.response?.data?.message || 'Failed to create post');
      }
    }
  };

  return (
    <div className="share">
      <form onSubmit={handleSubmit}>
        <div className="input-group">
          <img
            src={
              currentUser?.profilePicture
                ? currentUser.profilePicture.startsWith('http')
                  ? currentUser.profilePicture
                  : `http://localhost:5000${currentUser.profilePicture}?t=${new Date().getTime()}`
                : 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600'
            }
            alt={`${currentUser?.name}'s profile`}
          />
          <input
            type="text"
            placeholder={currentUser ? `What's on your mind, ${currentUser.name}?` : 'Login to share'}
            value={desc}
            onChange={(e) => setDesc(e.target.value)}
            disabled={!currentUser}
          />
        </div>
        <input
          type="file"
          accept="image/*,video/*,audio/*"
          onChange={(e) => setFile(e.target.files[0])}
          disabled={!currentUser}
        />
        <button type="submit" disabled={!currentUser}>Share</button>
        {error && <p className="error">{error}</p>}
      </form>
    </div>
  );
};

export default Share;
